import{_ as a,o as t,c as i,ag as o}from"./chunks/framework.BpToWd9i.js";const u=JSON.parse('{"title":"Make MAVSDK Release","description":"","frontmatter":{"github_branch":"main"},"headers":[],"relativePath":"en/cpp/contributing/release.md","filePath":"en/cpp/contributing/release.md"}'),l={name:"en/cpp/contributing/release.md"};function s(n,e,r,c,d,p){return t(),i("div",null,e[0]||(e[0]=[o(`<h1 id="make-mavsdk-release" tabindex="-1">Make MAVSDK Release <a class="header-anchor" href="#make-mavsdk-release" aria-label="Permalink to &quot;Make MAVSDK Release&quot;">​</a></h1><p>These are the instructions on how to get a release out the door.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The idea is of course to automate this as much as possible.</p></div><h2 id="mavsdk-part" tabindex="-1">MAVSDK part <a class="header-anchor" href="#mavsdk-part" aria-label="Permalink to &quot;MAVSDK part&quot;">​</a></h2><ol><li>Check if all open pull requests are merged that need to go in.</li><li>Check that CI on <code>main</code> passed.</li><li>Create tag in <code>main</code>:<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git switch main</span></span>
<span class="line"><span>git pull</span></span>
<span class="line"><span>git tag vX.Y.Z</span></span>
<span class="line"><span>git push origin vX.Y.Z</span></span></code></pre></div></li><li><ul><li>Update the version branch (e.g. <code>v4</code>) as well to track main.</li><li>Create the release on GitHub for the pushed tag. Generate the changelog using the GitHub button.</li></ul></li><li>Check later if all artifacts have been uploaded correctly to the release.</li><li>Update the Arch AUR repository. This depends on the AUR maintainer&#39;s credentials (currently julianoes). <ul><li>Use the repo: <code>ssh://aur@aur.archlinux.org/mavsdk.git</code>.</li><li>Bump the version in <code>pkgver=X.Y.Z</code>.</li><li>Check PKGBUILD: <code>namcap PKGBUILD</code>.</li><li>Try to make pkg: <code>makepkg</code>.</li><li>Update <code>.SRCINFO</code>: <code>makepkg --printsrcinfo &gt; .SRCINFO</code>.</li><li>Commit and push.</li></ul></li><li>Update the brew repo. Steps for macOS: <ul><li><code>export HOMEBREW_GITHUB_API_TOKEN=&lt;GITHUB API TOKEN&gt;</code></li><li><code>brew bump-formula-pr mavsdk --tag=vX.Y.Z --revision=&lt;GIT HASH&gt;</code></li><li>This should then open the browser with the pull request already created.</li></ul></li></ol><h2 id="documentation-part" tabindex="-1">Documentation part <a class="header-anchor" href="#documentation-part" aria-label="Permalink to &quot;Documentation part&quot;">​</a></h2><p>Documentation is now in-tree under the <code>docs/</code> folder in this repository, so it is released together with the code.</p><ol><li><a href="./../guide/build_docs.html">Generate the API reference docs</a> and commit any changes to <code>docs/en/cpp/api_reference/</code>.</li><li>Check or update the examples and guides in <code>docs/en/</code> as needed.</li></ol><h2 id="other" tabindex="-1">Other <a class="header-anchor" href="#other" aria-label="Permalink to &quot;Other&quot;">​</a></h2><ol><li>Post a note on Discord #mavsdk.</li></ol>`,10)]))}const m=a(l,[["render",s]]);export{u as __pageData,m as default};
